import { dataRefLabel, optionalString, plainObject, resourceRefLabel } from "../../engine/pull/context.js";
import { scopedLabelToBagKey, tfLabelToTsLabel } from "../../engine/tf/index.js";
import { AGENT_RESOURCE_TYPE } from "../agent/module.js";
import { APP_RESOURCE_TYPE } from "../app/module.js";
import { callerAccessMode } from "./types.js";
const KNOWN_ATTRS = new Set([
    "app_id", "provider_id", "agent_id", "caller_access_mode", "twilio_existing_number",
    "twilio_new_number", "registration",
]);
const CALLER_ACCESS_MODES = new Set(Object.values(callerAccessMode));
function isCallerAccessMode(value) {
    return CALLER_ACCESS_MODES.has(value);
}
export function phoneServiceFromTf(block, opts, ctx) {
    const label = block.label ?? "";
    const where = `phone service "${label}"`;
    for (const key of Object.keys(block.attrs)) {
        if (!KNOWN_ATTRS.has(key))
            ctx.diagnostics.push(`${where}: unhandled attribute "${key}" — extend phoneServiceFromTf deliberately`);
    }
    if (resourceRefLabel(block.attrs["app_id"], APP_RESOURCE_TYPE) !== opts.appLabel) {
        ctx.diagnostics.push(`${where}: app_id does not reference ${APP_RESOURCE_TYPE}.${opts.appLabel}; skipped`);
        return undefined;
    }
    const agentLabel = resourceRefLabel(block.attrs["agent_id"], AGENT_RESOURCE_TYPE);
    if (agentLabel === undefined) {
        ctx.diagnostics.push(`${where}: agent_id is not a managed ${AGENT_RESOURCE_TYPE} reference; skipped`);
        return undefined;
    }
    const providerLabel = dataRefLabel(block.attrs["provider_id"], "elementum_phone_provider");
    const providerName = providerLabel !== undefined ? ctx.dataName("elementum_phone_provider", providerLabel) : undefined;
    if (providerLabel === undefined || providerName === undefined) {
        ctx.diagnostics.push(`${where}: provider_id is not a resolvable elementum_phone_provider data reference; skipped`);
        return undefined;
    }
    const existing = plainObject(block.attrs["twilio_existing_number"]);
    const created = plainObject(block.attrs["twilio_new_number"]);
    const existingNumber = existing?.["phone_number"];
    const areaCode = created?.["area_code"];
    const hasExisting = typeof existingNumber === "string" && /^\+[1-9]\d{7,14}$/.test(existingNumber);
    const hasCreated = typeof areaCode === "number" && Number.isInteger(areaCode);
    if (hasExisting === hasCreated) {
        ctx.diagnostics.push(`${where}: expected exactly one valid Twilio existing number or new area code; skipped`);
        return undefined;
    }
    const callerAccess = optionalString(block.attrs, "caller_access_mode", where, ctx);
    if (callerAccess !== undefined && !isCallerAccessMode(callerAccess)) {
        ctx.diagnostics.push(`${where}: unsupported caller_access_mode "${callerAccess}"; omitted`);
    }
    const registrationRaw = plainObject(block.attrs["registration"]);
    const preferred = registrationRaw?.["preferred_languages"];
    const preferredLanguages = Array.isArray(preferred) && preferred.every((value) => typeof value === "string")
        ? preferred
        : undefined;
    if (preferred !== undefined && preferredLanguages === undefined) {
        ctx.diagnostics.push(`${where}: preferred_languages is not a string list; omitted`);
    }
    return {
        refName: scopedLabelToBagKey(opts.appLabel, label, "app"),
        agentKey: scopedLabelToBagKey(opts.appLabel, agentLabel, "app"),
        providerKey: tfLabelToTsLabel(providerLabel),
        ...(callerAccess !== undefined && isCallerAccessMode(callerAccess) ? { callerAccessMode: callerAccess } : {}),
        ...(hasExisting ? { twilioExistingNumber: { phoneNumber: existingNumber } } : {}),
        ...(hasCreated ? { twilioNewNumber: { areaCode: areaCode } } : {}),
        ...(registrationRaw !== undefined ? {
            registration: {
                ...(typeof registrationRaw["generate_first_message"] === "boolean" ? { generateFirstMessage: registrationRaw["generate_first_message"] } : {}),
                ...(typeof registrationRaw["expand_languages"] === "boolean" ? { expandLanguages: registrationRaw["expand_languages"] } : {}),
                ...(typeof registrationRaw["default_language"] === "string" ? { defaultLanguage: registrationRaw["default_language"] } : {}),
                ...(typeof registrationRaw["enable_language_routing"] === "boolean" ? { enableLanguageRouting: registrationRaw["enable_language_routing"] } : {}),
                ...(preferredLanguages !== undefined ? { preferredLanguages } : {}),
            },
        } : {}),
    };
}
